from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_val: str = Form(...), file_val: UploadFile = File(...)):
    return {"form_val": form_val, "file_val": file_val.filename}

client = TestClient(app)

def test_repro():
    # This should work if the bug is fixed, but fail (422) if the bug exists.
    # We need to send multipart/form-data.
    files = {"file_val": ("filename", "content", "text/plain")}
    data = {"form_val": "some_value"}
    response = client.post("/test", data=data, files=files)
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_repro()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
